"""Stored-state checks for OpenMail tasks.

OpenMail keeps its whole mailbox in the browser Local Storage document
``openmail.localState.v1``: the account, the settings, the labels, the contacts
and every message with its folder, labels, flags and recipients.  A task ends
with a specific mailbox, so that document is the durable outcome this module
judges.

Three task shapes are covered:

* :class:`OpenMailBrowserStorageEvaluator` checks declared account settings,
  declared messages with their labels and flags, and declared visible texts.
* :class:`OpenMailContactsReceiptReviewEvaluator` checks the replies, forwards,
  labels and discarded drafts named by a workflow contract.
* :class:`OpenMailWorkflowEvaluator` checks a named-expectation contract or a
  message/sent-message outcome table.

The document is read through the runtime controller; when no controller is
present the Local Storage directory is read in-process.  A missing document is
reported as a plain failure: the mailbox the task asks for has not been
produced.
"""

from __future__ import annotations

import json
import os
from typing import Any, Mapping

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus
from evaluators.cua_review.platforms.linux.local_storage import LOCAL_STORAGE_SOURCE, guest_path, read_state

__all__ = [
    "OpenMailBrowserStorageEvaluator",
    "OpenMailContactsReceiptReviewEvaluator",
    "OpenMailWorkflowEvaluator",
]

STATE_KEY = "openmail.localState.v1"

DEFAULT_STORAGE_DIRS = (
    "$HOME/.config/google-chrome/Default/Local Storage/leveldb",
    "$HOME/.config/chromium/Default/Local Storage/leveldb",
)

DEFAULT_TIMEOUT = 60


def storage_program(directory: str, key: str) -> str:
    """Build a standalone program that prints the stored document for ``key``."""
    tail = "\nprint(json.dumps(read_state(%s, %s), ensure_ascii=False))\n" % (
        json.dumps(directory),
        json.dumps(key),
    )
    return LOCAL_STORAGE_SOURCE + tail


def read_state_document(context: Mapping[str, Any], params: Mapping[str, Any]) -> tuple[Any, str | None]:
    """Return ``(state, directory)`` for the OpenMail document, or ``(None, None)``."""
    key = str(params.get("storage_key") or STATE_KEY)
    declared = params.get("storage_dirs") or params.get("leveldb_dir") or params.get("profile_dir")
    dirs: list[str] = []
    if isinstance(declared, (list, tuple)):
        dirs.extend(str(item) for item in declared if item)
    elif declared:
        dirs.append(str(declared))
    for root in DEFAULT_STORAGE_DIRS:
        if root not in dirs:
            dirs.append(root)
    timeout = int(params.get("timeout", DEFAULT_TIMEOUT) or DEFAULT_TIMEOUT)

    controller = context.get("controller")
    if controller is not None and hasattr(controller, "run_python_script"):
        for directory in dirs:
            expanded = guest_path(directory)
            raw = controller.run_python_script(storage_program(expanded, key), timeout=timeout)
            if not isinstance(raw, Mapping):
                continue
            if int(raw.get("returncode", -1)) != 0:
                continue
            output = str(raw.get("stdout") or raw.get("output") or "").strip()
            try:
                state = json.loads(output.splitlines()[-1])
            except (ValueError, IndexError):
                continue
            if state is not None:
                return state, expanded
        return None, None

    for directory in dirs:
        expanded = os.path.expandvars(os.path.expanduser(directory))
        state = read_state(expanded, key)
        if state is not None:
            return state, expanded
    return None, None


def _state_text(state: Any) -> str:
    try:
        return json.dumps(state, ensure_ascii=False)
    except (TypeError, ValueError):
        return str(state)


def _messages(state: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    return [item for item in (state.get("messages") or []) if isinstance(item, Mapping)]


def _recipients(message: Mapping[str, Any], field: str) -> list[str]:
    values = []
    for item in message.get(field) or []:
        if isinstance(item, Mapping):
            values.append(str(item.get("email") or ""))
        else:
            values.append(str(item))
    return values


def _labels_of(message: Mapping[str, Any]) -> list[str]:
    raw = message.get("labels")
    if raw is None:
        return []
    if isinstance(raw, str):
        return [part.strip() for part in raw.split(",") if part.strip()]
    if isinstance(raw, (list, tuple, set)):
        return [str(item) for item in raw]
    return [str(raw)]


def _as_list(value: Any) -> list[Any]:
    """Return a declared expectation as a list, keeping a bare string whole."""
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, (list, tuple, set)):
        return list(value)
    return [value]


def _message_text(message: Mapping[str, Any]) -> str:
    parts = [
        str(message.get("subject") or ""),
        str(message.get("body") or ""),
        str((message.get("from") or {}).get("name") if isinstance(message.get("from"), Mapping) else ""),
        " ".join(_recipients(message, "to")),
        " ".join(_recipients(message, "cc")),
        " ".join(_labels_of(message)),
    ]
    return "\n".join(parts)


def _check(check_id: str, expected: Any, observed: Any, passed: bool) -> dict[str, Any]:
    return {"check_id": check_id, "passed": bool(passed), "expected": expected, "observed": observed}


def _finish(evaluator: BaseEvaluator, metadata: dict[str, Any]) -> EvalResult:
    checks = metadata.get("checks") or []
    failed = [item["check_id"] for item in checks if not item["passed"]]
    metadata["failures"] = failed
    if not checks:
        metadata["status"] = "fail"
        return EvalResult(
            status=EvalStatus.FAIL,
            message="the task declares no OpenMail state to verify",
            metadata=metadata,
        )
    if failed:
        metadata["status"] = "fail"
        return EvalResult(
            status=EvalStatus.FAIL,
            message="OpenMail state checks failed: %s" % ", ".join(failed[:8]),
            metadata=metadata,
        )
    metadata["status"] = "pass"
    return EvalResult(status=EvalStatus.PASS, message=evaluator.PASS_MESSAGE, metadata=metadata)


class OpenMailBrowserStorageEvaluator(BaseEvaluator):
    """Verify declared settings, messages, labels and visible texts."""

    PASS_MESSAGE = "OpenMail browser storage checks passed"
    FAIL_MESSAGE = "OpenMail browser storage checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        state, directory = read_state_document(context, params)
        if not isinstance(state, Mapping):
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenMail mailbox document is absent: %s" % str(params.get("storage_key") or STATE_KEY),
            )

        checks: list[dict[str, Any]] = []
        messages = _messages(state)
        corpus = _state_text(state)

        settings = state.get("settings") if isinstance(state.get("settings"), Mapping) else {}
        expected_settings = params.get("settings") if isinstance(params.get("settings"), Mapping) else {}
        if expected_settings:
            if "display_name" in expected_settings:
                wanted = str(expected_settings.get("display_name"))
                seen = str(settings.get("displayName") or "")
                checks.append(_check("settings.display_name", wanted, seen, seen == wanted))
            if "email" in expected_settings:
                wanted = str(expected_settings.get("email"))
                seen = str(settings.get("email") or "")
                checks.append(_check("settings.email", wanted, seen, seen == wanted))
            if "signature_enabled" in expected_settings:
                wanted = bool(expected_settings.get("signature_enabled"))
                seen = bool(settings.get("autoSignature"))
                checks.append(_check("settings.signature_enabled", wanted, seen, seen == wanted))
            if "signature" in expected_settings:
                wanted = str(expected_settings.get("signature"))
                seen = str(settings.get("signature") or "")
                checks.append(_check("settings.signature", wanted, seen, seen == wanted))

        for text in list(params.get("required_global_texts") or []):
            wanted = str(text)
            checks.append(_check("global_text:%s" % wanted, wanted, wanted if wanted in corpus else None, wanted in corpus))

        for expectation in list(params.get("required_messages") or []):
            if not isinstance(expectation, Mapping):
                continue
            subject = str(expectation.get("subject") or "")
            matches = [item for item in messages if str(item.get("subject") or "") == subject]
            label = subject or "message"
            checks.append(_check("message:%s" % label, {"subject": subject}, {"count": len(matches)}, bool(matches)))
            if not matches:
                continue
            for wanted_label in _as_list(expectation.get("required_labels")):
                wanted = str(wanted_label)
                present = any(wanted in _labels_of(item) for item in matches)
                checks.append(_check("message_label:%s:%s" % (label, wanted), wanted, [ _labels_of(item) for item in matches ], present))
            if expectation.get("require_starred") is not None:
                wanted = bool(expectation.get("require_starred"))
                present = any(bool(item.get("starred")) == wanted for item in matches)
                checks.append(_check("message_starred:%s" % label, wanted, [bool(item.get("starred")) for item in matches], present))
            if expectation.get("require_unread") is not None:
                wanted = bool(expectation.get("require_unread"))
                present = any(bool(item.get("unread")) == wanted for item in matches)
                checks.append(_check("message_unread:%s" % label, wanted, [bool(item.get("unread")) for item in matches], present))
            if expectation.get("priority") is not None:
                wanted = str(expectation.get("priority")).strip().casefold()
                present = any(
                    str(item.get("priority") or "").strip().casefold() == wanted
                    or (wanted == "high" and bool(item.get("important")))
                    for item in matches
                )
                checks.append(_check("message_priority:%s" % label, wanted, [item.get("priority") for item in matches], present))
            for text in _as_list(expectation.get("required_texts")):
                wanted = str(text)
                present = any(wanted in _message_text(item) for item in matches)
                checks.append(_check("message_text:%s:%s" % (label, wanted), wanted, present, present))
            for term in _as_list(expectation.get("required_folder_terms")):
                wanted = str(term).strip().casefold()
                present = any(str(item.get("folder") or "").strip().casefold() == wanted for item in matches)
                checks.append(_check("message_folder:%s:%s" % (label, wanted), wanted, [item.get("folder") for item in matches], present))

        for text in list(params.get("final_page_texts") or []):
            wanted = str(text)
            checks.append(_check("final_page_text:%s" % wanted, wanted, wanted if wanted in corpus else None, wanted in corpus))

        metadata = {
            "directory": directory,
            "message_count": len(messages),
            "checks": checks,
            "settings": settings,
        }
        return _finish(self, metadata)


class OpenMailContactsReceiptReviewEvaluator(BaseEvaluator):
    """Verify the replies, forwards, labels and discarded drafts of a workflow."""

    PASS_MESSAGE = "OpenMail workflow state checks passed"
    FAIL_MESSAGE = "OpenMail workflow state checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        state, directory = read_state_document(context, params)
        if not isinstance(state, Mapping):
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenMail mailbox document is absent: %s" % str(params.get("storage_key") or STATE_KEY),
            )

        messages = _messages(state)
        corpus = _state_text(state)
        expectations = params.get("expectations") if isinstance(params.get("expectations"), Mapping) else {}
        checks: list[dict[str, Any]] = []
        notes: list[str] = []

        for key, value in expectations.items():
            name = str(key)
            wanted = str(value)
            if name.startswith("discarded_"):
                if name.endswith("_subject"):
                    present = any(str(item.get("subject") or "") == wanted for item in messages)
                else:
                    present = wanted in corpus
                checks.append(_check("absent:%s" % name, {"text": wanted, "present": False}, {"present": present}, not present))
            elif name.endswith("_subject"):
                present = any(str(item.get("subject") or "") == wanted for item in messages)
                checks.append(_check("subject:%s" % name, wanted, present, present))
            elif name.endswith("_to") or name.endswith("_cc"):
                field = "to" if name.endswith("_to") else "cc"
                wanted_folded = wanted.strip().casefold()
                present = any(
                    wanted_folded in [address.strip().casefold() for address in _recipients(item, field)]
                    for item in messages
                )
                checks.append(_check("recipient:%s" % name, wanted, present, present))
            elif name.endswith("_append") or name.endswith("_body") or name.endswith("_reply"):
                present = any(wanted in str(item.get("body") or "") for item in messages)
                checks.append(_check("body:%s" % name, wanted, present, present))
            elif name.endswith("_label"):
                present = any(wanted.casefold() in [label.casefold() for label in _labels_of(item)] for item in messages)
                checks.append(_check("label:%s" % name, wanted, present, present))
            else:
                notes.append(name)

        metadata = {
            "directory": directory,
            "message_count": len(messages),
            "checks": checks,
            "unmapped_expectations": notes,
            "ui_only_conditions": [
                name
                for name in ("require_final_query_in_search_box", "final_search_query")
                if params.get(name) or (isinstance(expectations, Mapping) and expectations.get(name))
            ],
        }
        return _finish(self, metadata)


class OpenMailWorkflowEvaluator(BaseEvaluator):
    """Verify a named-expectation contract or a message outcome table."""

    PASS_MESSAGE = "OpenMail workflow checks passed"
    FAIL_MESSAGE = "OpenMail workflow checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        state, directory = read_state_document(context, params)
        if not isinstance(state, Mapping):
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenMail mailbox document is absent: %s" % str(params.get("storage_key") or STATE_KEY),
            )

        messages = _messages(state)
        checks: list[dict[str, Any]] = []

        if params.get("messages") is not None or params.get("sent_messages") is not None:
            checks.extend(self._table_checks(params, messages, state))
        else:
            expectations = params.get("expectations") if isinstance(params.get("expectations"), Mapping) else {}
            checks.extend(self._expectation_checks(expectations, messages))

        metadata = {
            "directory": directory,
            "message_count": len(messages),
            "checks": checks,
            "ui_only_conditions": [
                name for name in ("require_final_query_in_search_box",) if params.get(name)
            ],
        }
        return _finish(self, metadata)

    # ------------------------------------------------------------- contracts
    @staticmethod
    def _expectation_checks(expectations: Mapping[str, Any], messages: list[Mapping[str, Any]]) -> list[dict[str, Any]]:
        checks: list[dict[str, Any]] = []
        for key, value in expectations.items():
            name = str(key)
            wanted = str(value)
            if name.endswith("_subject"):
                present = any(str(item.get("subject") or "") == wanted or wanted in str(item.get("subject") or "") for item in messages)
                checks.append(_check("subject:%s" % name, wanted, present, present))
            elif name.endswith("_to") or name.endswith("_cc"):
                field = "to" if name.endswith("_to") else "cc"
                wanted_folded = wanted.strip().casefold()
                present = any(
                    wanted_folded in [address.strip().casefold() for address in _recipients(item, field)]
                    for item in messages
                )
                checks.append(_check("recipient:%s" % name, wanted, present, present))
            elif name.endswith("_append") or name.endswith("_body") or name.endswith("_reply") or name.endswith("_text"):
                present = any(wanted in str(item.get("body") or "") for item in messages)
                checks.append(_check("body:%s" % name, wanted, present, present))
            elif name.endswith("_label"):
                present = any(wanted.casefold() in [label.casefold() for label in _labels_of(item)] for item in messages)
                checks.append(_check("label:%s" % name, wanted, present, present))
        return checks

    @staticmethod
    def _table_checks(
        params: Mapping[str, Any],
        messages: list[Mapping[str, Any]],
        state: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        checks: list[dict[str, Any]] = []
        account_name = str(params.get("account_name") or "").strip()

        def candidates(item_id: Any) -> list[Mapping[str, Any]]:
            if item_id:
                return [item for item in messages if str(item.get("id") or "") == str(item_id)]
            return []

        for expectation in list(params.get("messages") or []):
            if not isinstance(expectation, Mapping):
                continue
            subject = str(expectation.get("subject") or "")
            matches = candidates(expectation.get("id"))
            if not matches:
                matches = [item for item in messages if str(item.get("subject") or "") == subject]
            label = str(expectation.get("id") or subject or "message")
            checks.append(_check("message:%s" % label, {"subject": subject}, {"count": len(matches)}, bool(matches)))
            if not matches:
                continue
            sender = str(expectation.get("sender") or "").strip()
            if sender:
                present = any(sender.casefold() in str((item.get("from") or {}).get("name") if isinstance(item.get("from"), Mapping) else "").casefold() for item in matches)
                checks.append(_check("message_sender:%s" % label, sender, [item.get("from") for item in matches], present))
            if expectation.get("folder"):
                wanted = str(expectation.get("folder")).strip().casefold()
                present = any(str(item.get("folder") or "").strip().casefold() == wanted for item in matches)
                checks.append(_check("message_folder:%s" % label, wanted, [item.get("folder") for item in matches], present))
            for wanted_label in _as_list(expectation.get("labels")):
                wanted = str(wanted_label)
                present = any(wanted.casefold() in [label.casefold() for label in _labels_of(item)] for item in matches)
                checks.append(_check("message_label:%s:%s" % (label, wanted), wanted, [_labels_of(item) for item in matches], present))
            for field, key in (("starred", "starred"), ("important", "important"), ("unread", "unread")):
                if expectation.get(field) is not None:
                    wanted = bool(expectation.get(field))
                    present = any(bool(item.get(key)) == wanted for item in matches)
                    checks.append(_check("message_%s:%s" % (field, label), wanted, [item.get(key) for item in matches], present))

        for expectation in list(params.get("sent_messages") or []):
            if not isinstance(expectation, Mapping):
                continue
            subject_contains = str(expectation.get("subject_contains") or expectation.get("subject") or "")
            to_address = str(expectation.get("to") or "").strip().casefold()
            matches = []
            for item in messages:
                if account_name and str((item.get("from") or {}).get("name") if isinstance(item.get("from"), Mapping) else "").strip() != account_name:
                    continue
                if subject_contains and subject_contains.casefold() not in str(item.get("subject") or "").casefold():
                    continue
                if to_address and to_address not in [address.strip().casefold() for address in _recipients(item, "to")]:
                    continue
                matches.append(item)
            label = str(expectation.get("id") or subject_contains or to_address or "sent")
            checks.append(_check("sent:%s" % label, dict(expectation), {"count": len(matches)}, bool(matches)))
            if not matches:
                continue
            body_contains = str(expectation.get("body_contains") or "")
            if body_contains:
                present = any(body_contains.rstrip(".").casefold() in str(item.get("body") or "").rstrip(".").casefold() for item in matches)
                checks.append(_check("sent_body:%s" % label, body_contains, present, present))
            if expectation.get("folder"):
                wanted = str(expectation.get("folder")).strip().casefold()
                present = any(str(item.get("folder") or "").strip().casefold() == wanted for item in matches)
                checks.append(_check("sent_folder:%s" % label, wanted, [item.get("folder") for item in matches], present))
            for wanted_label in _as_list(expectation.get("labels")):
                wanted = str(wanted_label)
                present = any(wanted.casefold() in [value.casefold() for value in _labels_of(item)] for item in matches)
                checks.append(_check("sent_label:%s:%s" % (label, wanted), wanted, [_labels_of(item) for item in matches], present))

        for term in list(params.get("required_final_terms") or []):
            wanted = str(term)
            corpus = _state_text(state)
            checks.append(_check("final_term:%s" % wanted, wanted, wanted if wanted in corpus else None, wanted in corpus))

        return checks
